class NotificationService {
  send(notification: any) {
    if (notification.type === 'email') {
      // format and send email
      sendEmail(notification);
    } else if (notification.type === 'sms') {
      // format and send sms
      sendSMS(notification);
    } else if (notification.type === 'push') {
      // format and send push
      sendPush(notification);
    }
  }
}

class PriceCalculator {
  calculate(order: any) {
    switch (order.type) {
      case 'retail': return this.calculateRetail(order);
      case 'wholesale': return this.calculateWholesale(order);
      case 'discounted': return this.calculateDiscounted(order);
      default: throw new Error('unknown order type');
    }
  }
}

